<?php
use App\Domain\Solutions\{SolutionManager,SolutionRegistry,SolutionRelationManager,SolutionViewData}; use App\Models\{HomepageItem,HomepageSection,NavigationItem,NavigationMenu,Page,Solution,SolutionCategory,User,WebsiteSetting}; use Illuminate\Support\Facades\{Cache,Http,Schema}; use Illuminate\Validation\ValidationException;
use function Pest\Laravel\mock;
function solutionAdmin(array $a=[]):User{return User::factory()->create(array_merge(['is_active'=>true,'email_verified_at'=>now()],$a));} function solutionsInstalled():void{mock(\App\Domain\Installation\InstalledState::class)->shouldReceive('isInstalled')->andReturnTrue();} function solutionPayload(array $o=[]):array{return array_merge(['title'=>'Cloud transformation','slug'=>'cloud-transformation','short_description'=>'Secure cloud delivery.','template'=>'standard','hero_style'=>'standard','robots_index'=>1,'robots_follow'=>1],$o);}
test('solution administration index create and preview require authentication active administrator and installed state',function(){solutionsInstalled();$s=Solution::factory()->create();foreach(['/content/solutions','/content/solutions/create',"/content/solutions/$s->id/preview"] as $url)$this->get($url)->assertRedirect('/login');$this->actingAs(solutionAdmin(['is_active'=>false]))->get('/content/solutions')->assertRedirect('/login');$admin=solutionAdmin();mock(\App\Domain\Installation\InstalledState::class)->shouldReceive('isInstalled')->andReturnFalse();$this->actingAs($admin)->get('/content/solutions')->assertRedirect();});
test('public index and public lifecycle prevent draft future archive leakage while due and published render',function(){$this->get('/solutions')->assertSuccessful();$draft=Solution::factory()->create(['slug'=>'draft']);$future=Solution::factory()->scheduled(now()->addHour())->create(['slug'=>'future']);$due=Solution::factory()->scheduled(now()->subMinute())->create(['slug'=>'due','title'=>'Due solution']);$published=Solution::factory()->published()->create(['slug'=>'published','title'=>'Published solution']);$old=Solution::factory()->archived()->create(['slug'=>'old']);foreach([$draft,$future,$old] as $s)$this->get("/solutions/$s->slug")->assertNotFound();$this->get('/solutions/due')->assertSuccessful()->assertSee('Due solution');$this->get('/solutions/published')->assertSuccessful()->assertSee('Published solution');});
test('solution validation normalizes unique and safe slugs and enforces registries assets CTA URL and SEO',function(){solutionsInstalled();$this->actingAs(solutionAdmin());WebsiteSetting::create(['site_name'=>'N','legal_name'=>'N','primary_email'=>'a@b.test','country_code'=>'GB','timezone'=>'UTC','site_url'=>'https://example.com']);$this->post(route('admin.solutions.store'),solutionPayload(['slug'=>' Cloud---Secure ']))->assertSessionHasNoErrors();expect(Solution::first()->slug)->toBe('cloud-secure');$this->post(route('admin.solutions.store'),solutionPayload(['slug'=>'cloud-secure']))->assertSessionHasErrors('slug');foreach(['create','preview','admin','api'] as $slug)$this->post(route('admin.solutions.store'),solutionPayload(['slug'=>$slug]))->assertSessionHasErrors('slug');foreach(['../x','nested/x','https://x.test'] as $slug)$this->post(route('admin.solutions.store'),solutionPayload(['slug'=>$slug]))->assertSessionHasErrors('slug');$this->post(route('admin.solutions.store'),solutionPayload(['template'=>'blade.path','hero_style'=>'raw']))->assertSessionHasErrors(['template','hero_style']);$this->post(route('admin.solutions.store'),solutionPayload(['featured_image_path'=>'https://evil.test/a.png','featured_image_alt'=>'A']))->assertSessionHasErrors('featured_image_path');$this->post(route('admin.solutions.store'),solutionPayload(['featured_image_path'=>'images/a.webp']))->assertSessionHasErrors('featured_image_alt');$this->post(route('admin.solutions.store'),solutionPayload(['primary_cta_label'=>'Go']))->assertSessionHasErrors('primary_cta_url');$this->post(route('admin.solutions.store'),solutionPayload(['primary_cta_label'=>'Go','primary_cta_url'=>'javascript:x']))->assertSessionHasErrors('primary_cta_url');$this->post(route('admin.solutions.store'),solutionPayload(['meta_title'=>str_repeat('x',71),'canonical_url'=>'https://evil.test/x']))->assertSessionHasErrors(['meta_title','canonical_url']);expect(SolutionRegistry::TEMPLATES)->toHaveCount(5)->and(SolutionRegistry::ICONS)->not->toContain('raw-svg');});
test('categories normalize unique ordering and restrictive dependencies',function(){solutionsInstalled();$this->actingAs(solutionAdmin());$this->post(route('admin.solutions.categories.store'),['name'=>'Digital','slug'=>' Digital Work ','is_active'=>1])->assertSessionHasNoErrors();$category=SolutionCategory::first();expect($category->slug)->toBe('digital-work')->and($category->display_order)->toBe(1);$this->post(route('admin.solutions.categories.store'),['name'=>'Again','slug'=>'digital-work'])->assertSessionHasErrors('slug');Solution::factory()->create(['solution_category_id'=>$category]);expect(fn()=>$category->delete())->toThrow(Throwable::class);});
test('children enforce maximum icons ordering numbering and confirmed leaf routes',function(){solutionsInstalled();$this->actingAs(solutionAdmin());$s=Solution::factory()->create();foreach(range(1,8) as $i)$s->processSteps()->create(['title'=>"Step $i",'description'=>'Safe','display_order'=>$i]);$this->post(route('admin.solutions.children.store',[$s,'process-steps']),['title'=>'Too many','description'=>'Safe','is_active'=>1])->assertSessionHasErrors();$this->post(route('admin.solutions.children.store',[$s,'features']),['title'=>'Bad','description'=>'Safe','icon'=>'<svg>','is_active'=>1])->assertSessionHasErrors('icon');$data=app(SolutionViewData::class)->preview($s);expect($data['process'])->toHaveCount(8);});
test('relations reject self duplicate maximum and archived targets while public targets remain bounded',function(){$s=Solution::factory()->create();$archived=Solution::factory()->archived()->create();expect(fn()=>app(SolutionRelationManager::class)->sync($s,[$s->id],[]))->toThrow(ValidationException::class)->and(fn()=>app(SolutionRelationManager::class)->sync($s,[$archived->id],[]))->toThrow(ValidationException::class);$targets=Solution::factory()->count(7)->create();expect(fn()=>app(SolutionRelationManager::class)->sync($s,$targets->pluck('id')->all(),[]))->toThrow(ValidationException::class);$page=Page::factory()->published()->create(['slug'=>'current']);app(SolutionRelationManager::class)->sync($s,[],[$page->id]);$page->update(['slug'=>'changed']);expect(app(SolutionViewData::class)->preview($s)['related_pages'][0]['url'])->toContain('/changed');});
test('publication scheduling unpublish archive restore and duplicate preserve structured content safely',function(){$m=app(SolutionManager::class);$admin=solutionAdmin();$s=Solution::factory()->create();$s->features()->create(['title'=>'Feature','description'=>'Safe','display_order'=>1]);$m->publish($s);expect($s->fresh()->published_at)->not->toBeNull();$m->unpublish($s);expect($s->fresh()->status)->toBe('draft')->and($s->short_description)->toBe($s->fresh()->short_description);$m->schedule($s,now()->addHour()->utc()->toDateTimeString());expect($s->fresh()->status)->toBe('scheduled');$m->archive($s);expect($s->fresh()->status)->toBe('archived');$m->restore($s);$copy=$m->duplicate($s,$admin->id);expect($copy->status)->toBe('draft')->and($copy->published_at)->toBeNull()->and($copy->slug)->not->toBe($s->slug)->and($copy->features)->toHaveCount(1);});
test('preview is protected uncached noindex banner and escapes draft content',function(){solutionsInstalled();$s=Solution::factory()->create(['overview'=>'<script>unsafe()</script>']);Cache::put('public.solutions.sentinel','cached');$this->actingAs(solutionAdmin())->get(route('admin.solutions.preview',$s))->assertSuccessful()->assertHeader('Cache-Control','no-store, private, max-age=0')->assertHeader('X-Robots-Tag','noindex, nofollow')->assertSee('Preview Mode')->assertSee('&lt;script&gt;unsafe()&lt;/script&gt;',false)->assertDontSee('<script>',false);});
test('homepage canonical references preserve fallback and hide unpublished links',function(){HomepageSection::create(['section_key'=>'featured_solutions','display_order'=>1,'is_enabled'=>true]);$section=HomepageSection::first();$published=Solution::factory()->published()->create(['title'=>'Canonical']);$item=$section->items()->create(['item_type'=>'solution','title'=>'Fallback','description'=>'Preview','solution_id'=>$published->id]);expect($item->solution->title)->toBe('Canonical');$published->update(['status'=>'draft','published_at'=>null]);expect($published->fresh()->isPubliclyVisible())->toBeFalse();});
test('navigation resolves current solution slug disables draft and blocks archive dependency',function(){$s=Solution::factory()->published()->create(['slug'=>'old']);$menu=NavigationMenu::create(['name'=>'Primary','location'=>'primary']);NavigationItem::create(['navigation_menu_id'=>$menu->id,'label'=>'Solution','link_type'=>'solution','solution_id'=>$s->id,'target'=>'_self']);$this->get('/')->assertSee('/solutions/old',false);$s->update(['slug'=>'new']);$this->get('/')->assertSee('/solutions/new',false);$s->update(['status'=>'draft','published_at'=>null]);$this->get('/')->assertDontSee('href="http://localhost/solutions/new"',false);expect(fn()=>app(SolutionManager::class)->archive($s))->toThrow(ValidationException::class);});
test('sitemap includes only public indexable solutions and public rendering makes no portal call or secret leak',function(){Solution::factory()->published()->create(['slug'=>'included','robots_index'=>true]);Solution::factory()->published()->create(['slug'=>'noindex','robots_index'=>false]);Solution::factory()->create(['slug'=>'draft']);Http::fake();$html=$this->get('/sitemap.xml')->assertSuccessful()->assertSee('/solutions')->assertSee('/solutions/included')->assertDontSee('/solutions/noindex')->assertDontSee('/solutions/draft')->getContent();Http::assertNothingSent();expect($html)->not->toContain('request_token','signed_entitlement','APP_KEY');});
test('phase nine b introduces no later module or authorization infrastructure',function(){expect(Schema::hasTable('solutions'))->toBeTrue()->and(Schema::hasTable('products'))->toBeFalse()->and(Schema::hasTable('industries'))->toBeFalse()->and(Schema::hasTable('media'))->toBeFalse()->and(Schema::hasTable('roles'))->toBeFalse()->and(Schema::hasTable('permissions'))->toBeFalse();});
